/**
 * Public enquiry reference formats. Current references are random (`ENQ-7F3A-9C21-B8D4`, 48 random bits generated by the
 * database); older enquiries keep their sequential `ENQ-2026-001000`. Every place that validates a reference must accept both.
 */
export const ENQUIRY_REFERENCE = /^ENQ-(?:\d{4}-\d{6}|[0-9A-F]{4}-[0-9A-F]{4}-[0-9A-F]{4})$/;
